#!/usr/bin/env python3
"""Compute the raw L2 norm of each client's update vector.

Reads config.json for the number of clients, loads each client's
update vector from clientN.json, and prints name + raw L2 norm.
"""

import json
import math


def load_json(path):
    with open(path) as f:
        return json.load(f)


def l2_norm(vec):
    return math.sqrt(sum(x * x for x in vec))


def main():
    config = load_json("config.json")
    num_clients = config["num_clients"]

    for i in range(1, num_clients + 1):
        name = f"client{i}"
        data = load_json(f"{name}.json")
        norm = l2_norm(data["update"])
        print(f"{name}: {norm:.4f}")


if __name__ == "__main__":
    main()

